<?php
require_once __DIR__ . '/../../includes/auth.php'; require_once __DIR__ . '/../../includes/rutinas.php'; requiereRol('ADMIN');
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); if ($id === false || $id === null) { header('Location: index.php'); exit; }
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'GET') { include __DIR__ . '/formulario.php'; exit; } if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { header('Location: index.php'); exit; }
$token = is_string($_POST['token'] ?? null) ? $_POST['token'] : ''; $idUsuario = filter_var($_POST['id_usuario'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); $nombre = is_string($_POST['nombre_rutina'] ?? null) ? trim($_POST['nombre_rutina']) : ''; $descripcion = is_string($_POST['descripcion'] ?? null) ? trim($_POST['descripcion']) : '';
$_SESSION['rutina_formulario'] = ['id' => (int) $id, 'id_usuario' => $idUsuario ?: 0, 'nombre_rutina' => $nombre, 'descripcion' => $descripcion];
if (!validarTokenCsrf($token) || $idUsuario === false || $idUsuario === null || $nombre === '' || mb_strlen($nombre) > 100) { $_SESSION['mensaje'] = 'El propietario es obligatorio y el nombre debe tener hasta 100 caracteres.'; header('Location: formulario.php?id=' . (int) $id); exit; }
try { if (!existeUsuarioRutina((int) $idUsuario)) throw new InvalidArgumentException('El usuario propietario no existe.'); if (obtenerRutina((int) $id) === null) throw new InvalidArgumentException('La rutina no existe.'); guardarRutina((int) $id, (int) $idUsuario, $nombre, $descripcion); unset($_SESSION['rutina_formulario']); $_SESSION['mensaje'] = 'Rutina modificada correctamente.'; } catch (InvalidArgumentException $exception) { $_SESSION['mensaje'] = $exception->getMessage(); header('Location: formulario.php?id=' . (int) $id); exit; } catch (RuntimeException $exception) { error_log($exception->getMessage()); $_SESSION['mensaje'] = 'No se pudo modificar la rutina.'; }
header('Location: index.php'); exit;
